test('reload updates and removes display names while retaining the three internal accounts', async () => {
  const mem = { accounts: fixtures() };
  const am = new AccountManager(mem.accounts);
  const disk = structuredClone(mem);
  disk.accounts[1].displayName = 'updated@example.invalid';
  await syncAccountsFromDisk(disk, mem, am);
  assert.equal(am.getStatus().accounts[1].displayName, 'updated@example.invalid');
  assert.equal(mem.accounts[1].displayName, 'updated@example.invalid');
  assert.equal(am.accounts[1].name, 'codex-1');
